using Mbb.Archive.BuildingBlocks.Domain;using Mbb.Archive.Modules.Retention.Domain.Rules;namespace Mbb.Archive.Modules.Retention.Domain.Cases;
public enum RetentionCaseStatus{Scheduled=0,Held=1,Eligible=2,Completed=3}
public sealed class RetentionCase:AggregateRoot<Guid>{private RetentionCase(){}private RetentionCase(Guid id,Guid recordId,Guid documentId,Guid ruleId,string ruleCode,DispositionAction action,DateTimeOffset triggerAt,DateTimeOffset? dueAt):base(id){ArchiveRecordId=recordId;DocumentId=documentId;RuleId=ruleId;RuleCode=ruleCode;Action=action;TriggerAt=triggerAt;DueAt=dueAt;Status=RetentionCaseStatus.Scheduled;ConcurrencyVersion=1;}public Guid ArchiveRecordId{get;private set;}public Guid DocumentId{get;private set;}public Guid RuleId{get;private set;}public string RuleCode{get;private set;}=string.Empty;public DispositionAction Action{get;private set;}public DateTimeOffset TriggerAt{get;private set;}public DateTimeOffset? DueAt{get;private set;}public RetentionCaseStatus Status{get;private set;}public int ActiveHoldCount{get;private set;}public long ConcurrencyVersion{get;private set;}public static RetentionCase Schedule(Guid recordId,Guid documentId,RetentionRule rule,DateTimeOffset declaredAt){DateTimeOffset? due=rule.Action==DispositionAction.KeepPermanent?null:declaredAt.AddMonths(rule.RetentionMonths);return new(Guid.CreateVersion7(),recordId,documentId,rule.Id,rule.Code,rule.Action,declaredAt,due);}public void PlaceHold(){ActiveHoldCount++;Status=RetentionCaseStatus.Held;ConcurrencyVersion++;}public void ReleaseHold(){if(ActiveHoldCount<=0)throw new DomainRuleViolationException("Retention case has no active legal hold.");ActiveHoldCount--;Status=ActiveHoldCount>0?RetentionCaseStatus.Held:RetentionCaseStatus.Scheduled;ConcurrencyVersion++;}public bool Evaluate(DateTimeOffset now){if(Status is RetentionCaseStatus.Eligible or RetentionCaseStatus.Completed)return false;if(ActiveHoldCount>0||DueAt is null||DueAt>now)return false;Status=RetentionCaseStatus.Eligible;ConcurrencyVersion++;return true;}}
public sealed class LegalHold:AggregateRoot<Guid>{private LegalHold(){}private LegalHold(Guid id,Guid caseId,Guid recordId,string reason,string placedBy,DateTimeOffset at):base(id){RetentionCaseId=caseId;ArchiveRecordId=recordId;Reason=reason;PlacedBy=placedBy;PlacedAt=at;}public Guid RetentionCaseId{get;private set;}public Guid ArchiveRecordId{get;private set;}public string Reason{get;private set;}=string.Empty;public string PlacedBy{get;private set;}=string.Empty;public DateTimeOffset PlacedAt{get;private set;}public DateTimeOffset? ReleasedAt{get;private set;}public bool IsActive=>ReleasedAt is null;public static LegalHold Place(Guid caseId,Guid recordId,string reason,string placedBy,DateTimeOffset at){if(string.IsNullOrWhiteSpace(reason))throw new DomainRuleViolationException("Legal hold reason is required.");return new(Guid.CreateVersion7(),caseId,recordId,reason.Trim(),placedBy.Trim(),at);}public void Release(DateTimeOffset at){if(ReleasedAt is not null)return;ReleasedAt=at;}}
